import React from "react";
import { Container, Carousel, Button } from "react-bootstrap";

// Simple Video carousel linking to the band's YouTube channel.
// Update `videoList` with specific `watch` URLs or embed IDs if you want modal playback.
const videoList = [
  {
    id: "channel",
    title: "Precious Blood - YouTube Channel",
    // default to the channel's videos page; replace with watch?id links for specific videos
    url: "https://www.youtube.com/@PreciousBloodMusic/videos",
    // we'll use an existing background image as a thumbnail placeholder
    thumb: "/img/bg-img/bg-images-3-1200.jpg",
  },
  {
    id: "channel-2",
    title: "Visit Precious Blood on YouTube",
    url: "https://www.youtube.com/@PreciousBloodMusic/videos",
    thumb: "/img/bg-img/bg-images-3-1200.jpg",
  },
];

export default function Video() {
  if (videoList.length === 0) return null;

  return (
    <section id="videos" className="video-area section-padding-100">
      <Container>
        <h3 className="mb-4">Videos</h3>
        <Carousel>
          {videoList.map((v) => (
            <Carousel.Item key={v.id}>
              <a href={v.url} target="_blank" rel="noopener noreferrer">
                <img
                  className="d-block w-100 rounded"
                  src={v.thumb}
                  alt={v.title}
                  style={{ maxHeight: 480, objectFit: "cover" }}
                />
              </a>
              <Carousel.Caption>
                <h5>{v.title}</h5>
                <p>
                  <Button
                    variant="light"
                    size="sm"
                    href={v.url}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    Watch on YouTube
                  </Button>
                </p>
              </Carousel.Caption>
            </Carousel.Item>
          ))}
        </Carousel>
      </Container>
    </section>
  );
}
